hits, rates, n = 0, [], 0
for name, text in CVS:
    try:
        res = match_cv_text(text, top_k=5)
    except Exception as e:
        print(f"{name}: EXTRACTION FAILED: {e}")
        continue
    jobs = res.get("jobs", [])
    flags = [1 if ((j.get("dim_scores") or {}).get("domain_fit", 0) or 0) >= 0.5 else 0 for j in jobs]
    hits += bool(flags and flags[0]); n += 1
    rates.append(sum(flags) / len(flags) if flags else 0)
print(f"SUMMARY-REAL: top1_on_domain = {hits}/{n} · mean on_domain@5 = {sum(rates)/max(n,1):.2f}")
